import csv, os
d = "C:/Users/eric_rash/Downloads"
fs = [os.path.join(d, "leaderboard.csv")] + [os.path.join(d, f"leaderboard ({i}).csv") for i in range(1, 22)]
print("headers sample:", list(csv.DictReader(open(fs[0], encoding="utf-8-sig")).fieldnames)[:14])
for f in fs:
    rows = list(csv.DictReader(open(f, encoding="utf-8-sig")))
    snaps = []
    for r in rows:
        try:
            snaps.append(int(float(r.get("Snaps", ""))))
        except ValueError:
            pass
    teams = {r.get("Team") for r in rows}
    col = [r.get("Snaps") for r in rows if "Colandrea" in (r.get("Player") or r.get("Name") or "")]
    print(os.path.basename(f), len(rows), "maxSnaps", max(snaps) if snaps else None, "teams", len(teams), "Colandrea", col)

