import csv
from collections import Counter, defaultdict
from pathlib import Path

d = Path("C:/Users/eric_rash/.claude/jobs/76d10890/tmp/010/csv")
by_scope = {"fbs": defaultdict(dict), "fcs": defaultdict(dict)}
for p in sorted(d.glob("*.csv")):
    scope = "fbs" if p.name.startswith("2025_fbs_") else "fcs"
    tab = "adv" if "advanced" in p.name else "trt"
    grp = p.name.split("_")[2]
    for r in csv.DictReader(open(p, encoding="utf-8-sig")):
        by_scope[scope][r["PlayerId"]][(tab, grp)] = r

print("files", len(list(d.glob("*.csv"))))
print("fbs ids", len(by_scope["fbs"]), "fcs_g6 ids", len(by_scope["fcs"]))
common = set(by_scope["fbs"]) & set(by_scope["fcs"])
print("overlap ids", len(common), "union", len(set(by_scope["fbs"]) | set(by_scope["fcs"])))

diffs = Counter()
examples = {}
compared = 0
for pid in common:
    for key, a in by_scope["fbs"][pid].items():
        b = by_scope["fcs"][pid].get(key)
        if b is None:
            continue
        compared += 1
        for col in a:
            if col in ("Rank",):
                continue
            if a.get(col) != b.get(col):
                diffs[col] += 1
                examples.setdefault(col, (pid, key, a.get(col), b.get(col)))
print("row pairs compared", compared)
print("diff columns", dict(diffs.most_common(15)))
for c, e in list(examples.items())[:8]:
    print(" ex", c, e)

teams = Counter()
for pid in common:
    for r in by_scope["fbs"][pid].values():
        teams[r["Team"]] += 1
        break
print("overlap teams", len(teams))

