const fs = require("fs");
const path = require("path");
const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell, WidthType,
  ShadingType, BorderStyle, PageOrientation, AlignmentType, LevelFormat, PageBreak,
} = require("docx");

const OUT = process.argv[2];
const rows = JSON.parse(fs.readFileSync(path.join(__dirname, "rows.json"), "utf8"));

const GREEN = "154734";
const GREY = "595959";
const FONT = "Arial";
const SHORT = {
  "Stops Allowed Over Expected": "Stops Allowed OE",
  "Run Stops Over Expected": "Run Stops OE",
  "Comp Rate Over Expected": "Comp Rate OE",
  "EPA Per Target": "EPA/Target",
};
const short = (s) => s.split(", ").map((m) => SHORT[m] || m).join(", ");

const run = (text, o = {}) => new TextRun({ text, font: FONT, size: o.size || 16, bold: o.bold, color: o.color, italics: o.italics });
const para = (children, o = {}) => new Paragraph({
  children: Array.isArray(children) ? children : [children],
  spacing: { before: o.before || 0, after: o.after === undefined ? 40 : o.after },
  alignment: o.align, numbering: o.bullet ? { reference: "bullets", level: 0 } : undefined,
});
const border = { style: BorderStyle.SINGLE, size: 4, color: "BFBFBF" };
const borders = { top: border, bottom: border, left: border, right: border };

const WIDTHS = [900, 4700, 1300, 2600, 1500, 1500, 1900];
const cell = (text, i, o = {}) => new TableCell({
  width: { size: WIDTHS[i], type: WidthType.DXA },
  borders,
  shading: o.fill ? { type: ShadingType.CLEAR, color: "auto", fill: o.fill } : undefined,
  margins: { top: 30, bottom: 30, left: 70, right: 70 },
  children: [para(run(text, { size: o.size || 15, bold: o.bold, color: o.color }), { after: 0 })],
});

const header = new TableRow({
  tableHeader: true,
  children: ["Role", "Core metrics (elite = 75th percentile or higher)", "Must-have (not under 25th)",
    "Minimum evidence (plus 300+ snaps)", "Board: total (Power Four)", "Exceptions X1 / X2 / X3",
    "Graded check: QS+ on board, on any list; FRP on board"]
    .map((t, i) => cell(t, i, { fill: GREEN, color: "FFFFFF", bold: true })),
});

const body = rows.map((r, idx) => {
  const k = Number(r.k);
  const n = r.core.split(", ").length;
  const pi = Number(r.pi_min);
  const evidence = `${k} of ${n} core metrics elite` + (pi ? `; Player Impact ${pi}+` : "; no Impact floor");
  const over = Number(r.board) > 50;
  const graded = Number(r.qs_n) + Number(r.frp_n) === 0 ? "no graded players"
    : `QS+ ${r.qs_board}/${r.qs_n}, ${r.qs_any}/${r.qs_n}; FRP ${r.frp_board}/${r.frp_n}`;
  const fill = idx % 2 ? "F2F2F2" : undefined;
  return new TableRow({
    cantSplit: true,
    children: [
      cell(r.role, 0, { bold: true, fill }),
      cell(short(r.core), 1, { fill }),
      cell(r.must, 2, { fill }),
      cell(evidence, 3, { fill }),
      cell(`${r.board} (${r.board_P4})${over ? " over target" : ""}`, 4, { fill, bold: over }),
      cell(`${r.x1_impact} / ${r.x2_speed} / ${r.x3_young}`, 5, { fill }),
      cell(graded, 6, { fill }),
    ],
  });
});

const h = (text) => para(run(text, { size: 20, bold: true, color: GREEN }), { before: 120, after: 40 });
const note = (text) => para(run(text, { size: 18, color: GREY }), { after: 40 });
const bullet = (parts) => para(parts.map(([t, b]) => run(t, { size: 18, bold: b })), { bullet: true, after: 30 });

const page1 = [
  para(run("BAYLOR PLAYER PERSONNEL // TELEMETRY x S.T.A.Q.S. // SCREENING MATRIX", { size: 24, bold: true, color: GREEN }), { after: 20 }),
  para(run("PROPOSED STAFF-REVIEW RULES, NOT WORKBOOK RULES. STAQS stays the grade of record; a name on a list is a reason to watch film, never a grade.", { size: 18, bold: true, color: GREY }), { after: 40 }),
  note("Pool: workbook 010, 2025 FBS + FCS players with Elig 1+ (still eligible after 2026). Target from the 2026-09-15 staff meeting: 30 to 50 pre-portal names per position by week 5 or 6. Every role uses the same template: 300+ snaps, the listed number of core metrics at the 75th percentile or higher, an optional Player Impact floor, and no must-have metric under the 25th percentile. Only the count and the floor change by role. Graded check: 000 POST-PORTAL RECAP, 39 players (28 graded QS or better, 11 FRP)."),
  new Table({ width: { size: WIDTHS.reduce((a, b) => a + b, 0), type: WidthType.DXA }, columnWidths: WIDTHS, rows: [header, ...body] }),
  para(run("Totals (unique names): 609 on a board; 340 more on an exception list only. Graded: 13 of 28 QS+ on a board, 17 of 28 on a board or exception list; 1 of 11 FRP kept. For scale, REVIEW with Sample OK keeps 21 of 28 QS+ and 5 of 11 FRP on 1,708 names.", { size: 16, color: GREY }), { before: 60, after: 0 }),
];

const page2 = [
  para(new PageBreak(), { after: 0 }),
  h("Roles"),
  bullet([["Split by Telemetry alignment code: ", true], ["OWR = WR, SWR = SLOT, OCB = CB, SCB = STAR, FS / SS = SAF, ILB = ILB, OLB = JACK. WR and SLOT share one core and differ in must-have (and, later, size).", false]]),
  bullet([["EDGE is screened for both END and JACK", true], [" and can sit on both lists. Stance (UP / DOWN) is not role: Harper Holloman (UP, graded AL) fails the JACK rule and passes END. This mapping is the least-tested assumption here.", false]]),
  h("Exception paths (a second tier, outside the 30 to 50)"),
  bullet([["X1 Impact: ", true], ["Player Impact 90+, 300+ snaps, one fewer elite core metric than the board needs (at least 1), no must-have deficiency.", false]]),
  bullet([["X2 Speed: ", true], ["Play Speed or Deep Speed 95+, Player Impact 60+, 150+ snaps, at least 1 elite core metric, no must-have deficiency.", false]]),
  bullet([["X3 Young: ", true], ["150 to 299 snaps, Elig 2+, and meets the role's board rule otherwise.", false]]),
  bullet([["Staff add: ", true], ["any name from film or contacts, unlimited. The data cannot see the players listed under blind spots.", false]]),
  h("Acceptable weaknesses"),
  bullet([["Any core metric other than the must-have may sit under the 25th percentile.", false]]),
  bullet([["Low Player Impact (10 or lower) stays on the board with a note, as decided 2026-09-16. ", false], ["17 board names carry it", true], [" (WR 3, SLOT 5, OT 7, STAR 2). Hardley Gilmore (graded QS, Impact 9) is why it is not a cut.", false]]),
  bullet([["Size is not gated yet. ", true], ["Proposed: undersized players stay only if X2 would also take them. Volume not sized.", false]]),
  h("Where the data falls short"),
  bullet([["NT (54) and END (53) are over target on purpose. ", true], ["NT's in-band option (4 elite core metrics, 30 names) keeps 0 of 7 graded QS+ front-line players; this rule keeps 3 on the board and 2 more through X1.", false]]),
  bullet([["OG/C: 0 of 4 graded QS+ kept. ", true], ["Church, Chester and Alo-Tupuola have Pass Blocking in the bottom 15 percent and were graded QS; Finau (AL) has Run Blocking at 1. OG/C boards should lean on staff adds.", false]]),
  bullet([["Blind spots, by name: ", true], ["Zashon Rich (CB, QS, Impact 3), Keaton Thomas (ILB, AL), DJ Lagway (QB, AL), Ryan Davis (EDGE, QS), Logan Moore (OT, QS), Hosea Wheeler and Kamren Washington (NT, AL and QS). None has enough elite core metrics or Impact to pass any rule without flooding the list.", false]]),
  h("Limits"),
  bullet([["Graded players: 28 QS+ and 11 FRP over 11 roles; RB, TE and SAF have none. Per-role hits are anecdotes, not rates. No LIM or NGE graded players, so rejection is untested.", false]]),
  bullet([["2025 data only. Pre-portal lists for 2026 need 2026 data (weeks 5 to 6) and a likely-to-enter signal the data does not have.", false]]),
  note("Method, alternatives per role and reproduce steps: repo PP_Recruiting, docs/2026-09-16-screening-matrix.md; harness scripts/size_matrix.py. Prepared 2026-09-16."),
];

const doc = new Document({
  styles: { default: { document: { run: { font: FONT, size: 18 } } } },
  numbering: {
    config: [{ reference: "bullets", levels: [{ level: 0, format: LevelFormat.BULLET, text: "•", alignment: AlignmentType.LEFT,
      style: { paragraph: { indent: { left: 360, hanging: 240 } } } }] }],
  },
  sections: [{
    properties: {
      page: {
        size: { width: 12240, height: 15840, orientation: PageOrientation.LANDSCAPE },
        margin: { top: 540, bottom: 540, left: 720, right: 720 },
      },
    },
    children: [...page1, ...page2],
  }],
});

Packer.toBuffer(doc).then((buf) => { fs.writeFileSync(OUT, buf); console.log("wrote", OUT); });

