$roots = @("C:\Users\eric_rash\Desktop\DEV", "C:\Users\eric_rash\Desktop\DEV\Football", "C:\Users\eric_rash\Desktop\DEV\SpecialRequests")
$repos = @("C:\Users\eric_rash\Desktop\DEV", "C:\Users\eric_rash\.claude", "C:\Users\eric_rash\.claude\skills", "C:\Users\eric_rash\.claude\global-memory",
           "C:\Users\eric_rash\Desktop\DEV\PP_Recruiting\.claude\worktrees\fireflies-review-board-0915")
foreach ($r in $roots) {
    if (Test-Path $r) {
        Get-ChildItem -Directory $r | Where-Object { Test-Path (Join-Path $_.FullName ".git") } | ForEach-Object { $repos += $_.FullName }
    }
}
$clean = 0
foreach ($repo in ($repos | Select-Object -Unique)) {
    $dirty = git -C $repo status --porcelain 2>$null
    $sb = git -C $repo status -sb 2>$null | Select-Object -First 1
    $ahead = $sb -match "ahead"
    $nobranch = -not ($sb -match "\.\.\.")
    if ($dirty -or $ahead) {
        $n = @($dirty).Count
        "DIRTY $repo | $sb | $n changed"
    } elseif ($nobranch) {
        "NOUPSTREAM $repo | $sb"
    } else { $clean++ }
